// sub_merge single-file build
// 直接粘贴到 Cloudflare Dashboard -> Workers & Pages -> 你的 Worker -> Edit code。
// 变量模式：在 Settings -> Variables and Secrets 设置一个 TOKEN（Secret）。
// 对外域名由请求 Origin 自动决定，无需配置。
// 存储：Cloudflare D1。绑定变量名必须是 DB（D1 database binding）。
// 建表：部署后调用一次 POST /api/v1/admin/schema（Bearer TOKEN），或在 Dashboard 的 D1 控制台执行 scripts/schema.sql。

/**
 * sub-merge
 *
 * 固定订阅入口 + 多机器自动上报 + WebUI 节点编辑/排序 + 客户端格式适配
 *
 * 存储：Cloudflare D1（SQLite），绑定变量名 DB
 *
 * 上报：POST /api/v1/report/:machine         Bearer TOKEN，body 为 base64 订阅
 * 读取：GET  /sub/:machine/:token           单机
 *       GET  /sub/all/:token                 全部机器
 *       GET  /sub/:token                     全部机器简写
 * 格式：?format=clash|singbox|base64，或 ?clash / ?singbox / ?b64
 * WebUI：GET /ui（入口路径可用 UI_PATH 改，例如 /x7q-entry）
 * API：GET/PUT /api/v1/nodes/:machine
 *      POST /api/v1/machines/:machine/reset
 *      POST /api/v1/admin/schema            建表（幂等）
 *
 * D1 表结构：
 *   machines(machine PK, content, hash, bytes, updated_at, nodes_json, manual)
 *     machine   : 机器 slug
 *     content   : base64 订阅原文
 *     hash      : content 的 SHA-256，用于去重
 *     nodes_json: [{id, name, link, protocol, order}] 的 JSON 文本
 *     manual    : 1 表示 WebUI 手动编辑过，自动上报不再覆盖
 *   settings(key PK, value)
 *     目前只存 machine_order -> JSON 数组
 */

const VERSION = "2.4.71";
const MAX_BODY = 512 * 1024;
/* 单条节点 link 的长度上限：和 putNodeConfig 里 parseLink 的 8192 保持一致。
   旧版档案成员用 2000，vless-reality 带 pqv（后量子参数）时一条 link 就 2.9KB，
   会被静默过滤掉，表现就是「勾了保存不上」。 */
const PRESET_LINK_MAX = 8192;
/* members / skips 整列存进 D1 一个 TEXT 列，给个体积上限兜底（D1 单行 1MB） */
const PRESET_SET_MAX = 512 * 1024;
/* 机器名：字母/数字（含中文等 Unicode 字母）+ 空格 _ . -，首字符必须是字母或数字 */
const MACHINE_RE = /^[\p{L}\p{N}][\p{L}\p{N} _.-]{0,63}$/u;
// 机器名里不该带「手动 / 上报 / 自动」：那是标签显示的运行状态，混进名字后没人分得清
const MACHINE_STATUS_SUFFIX = /(手动|上报|自动)$/u;
const MACHINE_STATUS_ERROR = "machine name must not end with 手动 / 上报 / 自动, that is the status tag";

/* D1 表结构；scripts/schema.sql 与本数组保持一致，供 wrangler d1 execute --file 使用。 */
export const SCHEMA_STATEMENTS = [
  `CREATE TABLE IF NOT EXISTS machines (
  machine    TEXT PRIMARY KEY,
  content    TEXT NOT NULL,
  hash       TEXT NOT NULL,
  bytes      INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL,
  nodes_json TEXT NOT NULL DEFAULT '[]',
  manual_nodes_json TEXT NOT NULL DEFAULT '[]',
  manual     INTEGER NOT NULL DEFAULT 0,
  auto_content TEXT,
  manual_updated_at TEXT,
  auto_order_json TEXT NOT NULL DEFAULT '[]'
)`,
  "CREATE INDEX IF NOT EXISTS idx_machines_updated_at ON machines (updated_at DESC)",
  `CREATE TABLE IF NOT EXISTS machine_former (
  alias  TEXT PRIMARY KEY,
  target TEXT NOT NULL
)`,
  "CREATE INDEX IF NOT EXISTS idx_machine_former_target ON machine_former (target)",
  `CREATE TABLE IF NOT EXISTS reports (
  machine    TEXT NOT NULL,
  source     TEXT NOT NULL,
  content    TEXT NOT NULL,
  hash       TEXT NOT NULL,
  bytes      INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL,
  nodes_json TEXT NOT NULL DEFAULT '[]',
  PRIMARY KEY (machine, source)
)`,
  "CREATE INDEX IF NOT EXISTS idx_reports_machine ON reports (machine)",
  `CREATE TABLE IF NOT EXISTS links (
  code TEXT PRIMARY KEY,
  preset TEXT NOT NULL,
  format TEXT NOT NULL DEFAULT '',
  note TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  hits INTEGER NOT NULL DEFAULT 0,
  last_at TEXT
)`,
  `CREATE TABLE IF NOT EXISTS presets (
  name       TEXT PRIMARY KEY,
  label      TEXT NOT NULL DEFAULT '',
  protos     TEXT NOT NULL DEFAULT '',
  tunnel     TEXT NOT NULL DEFAULT '',
  machines   TEXT NOT NULL DEFAULT '',
  format     TEXT NOT NULL DEFAULT '',
  token      TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  skips      TEXT NOT NULL DEFAULT '',
  members    TEXT NOT NULL DEFAULT '',
  mode       TEXT NOT NULL DEFAULT '',
  clash_mode TEXT NOT NULL DEFAULT 'inherit',
  sources    TEXT NOT NULL DEFAULT ''
)`,
  `CREATE TABLE IF NOT EXISTS settings (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
)`,
];

/* 老库补列：D1 的 ALTER TABLE 没有 IF NOT EXISTS，重复执行会报 duplicate column，这里按幂等处理。
 * auto_content 保存「最近一次自动上报的原文」，手动编辑时不动它，恢复自动上报时用它。
 * 老库里这一列是 NULL，等价于「没有可恢复的上报」，行为退化成旧逻辑。 */
export const MIGRATION_STATEMENTS = [
  "ALTER TABLE machines ADD COLUMN auto_content TEXT",
  "ALTER TABLE machines ADD COLUMN manual_nodes_json TEXT NOT NULL DEFAULT '[]'",
  "ALTER TABLE machines ADD COLUMN manual_updated_at TEXT",
  /* ② 上报列表的自定义显示顺序：存 link 去掉 #名字 之后的「身份」，按用户排的顺序。
     空数组 = 没排过，面板就按上报顺序（脚本打印的顺序）显示。 */
  "ALTER TABLE machines ADD COLUMN auto_order_json TEXT NOT NULL DEFAULT '[]'",
  "ALTER TABLE presets ADD COLUMN skips TEXT NOT NULL DEFAULT ''",  "ALTER TABLE presets ADD COLUMN members TEXT NOT NULL DEFAULT ''",
  "ALTER TABLE presets ADD COLUMN mode TEXT NOT NULL DEFAULT ''",
  "ALTER TABLE presets ADD COLUMN clash_mode TEXT NOT NULL DEFAULT 'inherit'",
  "ALTER TABLE presets ADD COLUMN sources TEXT NOT NULL DEFAULT ''",
];

