      label.title = "这条来源最近一次内容变化：" + (item.updated_at || "未知") + (item.updated_at ? "（" + agoText(item.updated_at) + "）" : "") + "；内容没变的上报不会刷新";
      // 自动层是只读快照：界面上不给删除入口，避免误删后再也拿不回来。要换内容就让脚本重新上报。
