      meta.appendChild(label); meta.appendChild(raw);
      var copy = document.createElement("button"); copy.type = "button"; copy.className = "nlcopy"; copy.textContent = "复制";
      copy.title = "复制这条节点的原串（" + node.link.length + " 字符）";
